arrayPipelines.data:
[
	{ $match: {{ pulse_filter_js.getMatchQuery() }}},
	 { $sort: { "calendar_meta.start_time": -1, call_id: 1 } },
	{ $project: {
	_id: 0,
	call_id: 1,
	call_name:       "$calendar_meta.title",
	call_start_time: "$calendar_meta.start_time",
	call_type: 1,
	users: { $ifNull: ["$assist_stats.users_joined", []] },
total_active_seconds: { $ifNull: ["$assist_stats.billing_meta.total_active_seconds", "$usage_transaction.total_active_seconds", 0] },
total_nudges:          { $ifNull: ["$assist_stats.nudges_delivered_total", 0] },
transactions_consumed: { $ifNull: ["$usage_transaction.transaction_value", 0] }
} }
]

formToNativeQuery.data:
